// commonMain
sealed interface AuthState {
  data object Anonymous : AuthState
  data class LoggedIn(val token: String) : AuthState
  data class Failed(val reason: String) : AuthState
}

// Exhaustive in Kotlin — and at every Swift call site too, because
// adding a case adds a parameter and Swift stops compiling.
fun AuthState.handle(
  onAnonymous: () -> Unit,
  onLoggedIn: (String) -> Unit,
  onFailed: (String) -> Unit,
) = when (this) {
  AuthState.Anonymous -> onAnonymous()
  is AuthState.LoggedIn -> onLoggedIn(token)
  is AuthState.Failed -> onFailed(reason)
}

