// ✅ A generic CLASS crosses: Swift sees Page<Post>
class Page<T>(val items: List<T>, val nextCursor: String?)

// ❌ A generic INTERFACE does not — ObjC protocols have no type parameters,
//    so Swift sees load() -> Any?
interface Repository<T> { suspend fun load(): T }

// ❌ A generic FUNCTION does not — the parameter has nowhere to go in a selector
fun <T> List<T>.secondOrNull(): T? = getOrNull(1)

// ❌ Generic + sealed: two unchecked casts at every Swift call site
sealed class Outcome<out T> {
  data class Ok<T>(val value: T) : Outcome<T>()
  data class Err(val message: String) : Outcome<Nothing>()
}

// ✅ The exported edge: concrete, non-generic, typed per case
sealed interface FeedOutcome {
  data class Ok(val page: Page<Post>) : FeedOutcome
  data class Err(val message: String) : FeedOutcome
}

class FeedApi(private val repo: FeedRepo) {
  suspend fun load(cursor: String?): FeedOutcome =
    runCatching { repo.page(cursor) }
      .fold({ FeedOutcome.Ok(it) }, { FeedOutcome.Err(it.message ?: "failed") })
}

