// ✅ Export the handle, not the suspend function
class TaskHandle(private val job: Job) {
  fun cancel() = job.cancel()
  val isRunning: Boolean get() = job.isActive
}

class UserFacade(private val scope: CoroutineScope, private val api: UserApi) {
  fun fetchUser(
    id: Long,
    onSuccess: (User) -> Unit,
    onError: (String) -> Unit,
  ): TaskHandle = TaskHandle(
    scope.launch {
      try {
        onSuccess(api.fetchUser(id))
      } catch (e: CancellationException) {
        throw e                                  // cancellation is not an error
      } catch (e: Throwable) {
        onError(e.message ?: "failed")
      }
    }
  )
}

