// ✅ Values, not control flow — every failure the UI handles is a case
sealed interface FeedResult {
  data class Ok(val posts: List<Post>) : FeedResult
  data object Offline : FeedResult
  data object Unauthorized : FeedResult
  data class Failed(val message: String) : FeedResult
}

class FeedApi(private val client: HttpClient) {
  suspend fun loadFeed(): FeedResult = try {
    FeedResult.Ok(client.get("/feed").body())
  } catch (e: CancellationException) {
    throw e                                        // never swallow cancellation
  } catch (e: ClientRequestException) {
    if (e.response.status == HttpStatusCode.Unauthorized) FeedResult.Unauthorized
    else FeedResult.Failed(e.message)
  } catch (e: HttpRequestTimeoutException) {
    FeedResult.Offline
  } catch (e: Throwable) {
    FeedResult.Failed(e.message ?: "unknown error")
  }
}

