class ProfileVm(private val repo: ProfileRepo) {
  private val cache = mutableMapOf<String, String>()
  lateinit var user: User                        // read before load() -> process kill
  fun avatarUrl(): String = user.avatar!!        // NPE -> process kill, not an error

  fun applyName(name: String) {                  // header says _Nonnull; nothing checks
    cache[name.lowercase()] = name               // nil arrives HERE, no Swift frames
  }
}

