// ✅ Nullable at the edge, validated once, failures returned as values
class ProfileFacade(private val repo: ProfileRepo) {
  private var user: User? = null

  fun applyName(name: String?): NameResult {
    val trimmed = name?.trim().orEmpty()
    if (trimmed.isEmpty()) return NameResult.Invalid("name is required")
    val current = user ?: return NameResult.NotLoaded
    user = current.copy(name = trimmed)
    return NameResult.Ok(trimmed)
  }

  fun avatarUrl(): String? = user?.avatar        // optional in Swift, checked by Swift
}

sealed interface NameResult {
  data class Ok(val name: String) : NameResult
  data class Invalid(val reason: String) : NameResult
  data object NotLoaded : NameResult
}

// ✅ Wrap the unaudited API once, and the nil is handled where it appears
@OptIn(ExperimentalForeignApi::class)
fun sessionTokenOrNull(): String? = VendorSdk.shared().currentToken()

