class Cancellable(private val onCancel: () -> Unit) { fun cancel() = onCancel() }

// ❌ A singleton owning the scope: the screen has no way to end its own work
object FeedHub {
  private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Main)
  private val listeners = mutableListOf<(List<Post>) -> Unit>()

  fun observe(onEach: (List<Post>) -> Unit) {        // nothing to unsubscribe with
    listeners += onEach                              // holds the Swift block forever
    scope.launch { repo.posts().collect { p -> listeners.forEach { it(p) } } }
  }
}

// ✅ Scope per screen, and every subscription returns its own handle
class FeedViewModel(private val repo: FeedRepo) {
  private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Main)

  init { live++ }                                    // an instance count beats a hunch

  fun observe(onEach: (List<Post>) -> Unit): Cancellable {
    val job = repo.posts().onEach(onEach).launchIn(scope)
    return Cancellable { job.cancel() }
  }

  fun close() { scope.cancel(); live-- }

  companion object { var live = 0 }                  // only touched on Dispatchers.Main
}

// Swift, in comments — the two lines that decide the lifetime:
//   .task { handle = vm.observe { [weak self] posts in self?.posts = posts } }
//   deinit { handle?.cancel(); vm.close() }   // close() is what frees the Kotlin side

class FeedViewModel(private val repo: FeedRepo) {
  private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Main)

  private val _state = MutableStateFlow<FeedState>(FeedState.Loading)
  val state: StateFlow<FeedState> = _state

  // ❌ loads and publishes on a background thread: Swift's callback runs off main
  fun loadWrong() = scope.launch(Dispatchers.Default) {
    _state.value = FeedState.Ready(repo.load())
  }

  // ✅ heavy work off main, one visible hop back before anything observable changes
  fun load() = scope.launch {
    val posts = withContext(Dispatchers.Default) { repo.load() }
    _state.value = FeedState.Ready(posts)          // scope is Dispatchers.Main
  }

  fun observe(onEach: (FeedState) -> Unit): Cancellable {
    val job = state.onEach(onEach).launchIn(scope)  // main scope, so onEach is on main
    return Cancellable { job.cancel() }
  }

  fun close() = scope.cancel()
}

