@OptIn(ExperimentalObjCRefinement::class)
class FeedViewModel(private val repo: FeedRepo) {   // FeedRepo is internal, never exported

  private val scope = MainScope()

  // The whole screen as one value: Swift renders this and nothing else.
  data class State(
    val posts: List<Post>,
    val isRefreshing: Boolean,
    val errorText: String?,        // an error as data, not an exception across the bridge
  )

  private val _state = MutableStateFlow(State(emptyList(), false, null))

  fun observe(onEach: (State) -> Unit): Cancellable {
    val job = _state.onEach(onEach).launchIn(scope)
    return Cancellable { job.cancel() }
  }

  fun refresh() { scope.launch { _state.value = _state.value.copy(posts = repo.load()) } }

  fun toggleBookmark(postId: String) { scope.launch { repo.toggle(postId) } }

  @HiddenFromObjC                  // public for Android tests, invisible to Swift
  fun debugDump(): String = _state.value.toString()

  @ShouldRefineInSwift             // exported as __states(), wrapped by a Swift extension
  fun states(): Flow<State> = _state
}

